args.command:
source /tmp/probe_misc/env.sh; cd /tmp/probe_misc
rm -rf home/.cache/direnv; : > httpd3.log
PID=$(pgrep -f 'python3 -m http[.]server' | head -1); echo "server PID=$PID"
req(){ grep -c GET httpd3.log 2>/dev/null || echo 0; }
cas(){ ls home/.cache/direnv/cas/ 2>/dev/null | tr '\n' ' '; }
step(){ echo "== $1"; shift; /workspace/executable "$@" >o.bin 2>e.bin; echo "exit=$? stdout=[$(cat o.bin)] stderr=[$(cat e.bin | sed 's/\x1b/ESC/g')]"; echo "   GETs=$(req) CAS: $(cas)"; }
# NB: server log is httpd2.log (started with >httpd2.log). Use that.
req(){ grep -c GET httpd2.log; }
step "A cold url+hash correct" fetchurl http://127.0.0.1:18231/file.txt sha256-I+TKTGAt2yd0arQXIrTfpUZimdSv4mNJQyVKWinF5IU=
step "B warm url+hash correct" fetchurl http://127.0.0.1:18231/file.txt sha256-I+TKTGAt2yd0arQXIrTfpUZimdSv4mNJQyVKWinF5IU=
step "C warm url-only" fetchurl http://127.0.0.1:18231/file.txt
step "D warm url+hash WRONG" fetchurl http://127.0.0.1:18231/file.txt sha256-AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=
step "E after-wrong, url+hash correct again" fetchurl http://127.0.0.1:18231/file.txt sha256-I+TKTGAt2yd0arQXIrTfpUZimdSv4mNJQyVKWinF5IU=
